  1: 'use strict';
  2: // s4_warmup.cjs (warmup-1.0) - S4-0 warmup sensitivity. Read-only on engines and data.
  3: // Question: with fewer warmup bars than REF, does the frozen engine give the SAME trades on the target day?
  4: // Method: stock-days with >= REF prior bars; cut warmup to W bars; rerun; compare with the REF run trade by trade.
  5: // Note: REF is itself a truncation of history. This measures convergence to the REF run.
  6: // Loaders copied verbatim from sz-lab-guard11.cjs (parity 48 passed).
  7: const fs = require('fs'), path = require('path'), crypto = require('crypto');
  8: const VER = 'warmup-1.0', STEP = 'S4.warmup';
  9: const ROOT = path.resolve(process.argv[2] || '.');
 10: const A = k => { const i = process.argv.indexOf('--' + k); return i > 2 && i + 1 < process.argv.length ? process.argv[i + 1] : ''; };
 11: const T0 = Date.now(), D0 = new Date();
 12: const p2 = n => String(n).padStart(2, '0');
 13: const LSTAMP = D0.getFullYear() + p2(D0.getMonth() + 1) + p2(D0.getDate()) + '-' + p2(D0.getHours()) + p2(D0.getMinutes()) + p2(D0.getSeconds());
 14: const OUTF = path.join(ROOT, 'out', 'FOR_OPUS.txt');
 15: const RDIR = path.join(ROOT, 'out', 'reports', STEP + '_' + LSTAMP);
 16: const chk = [], sums = [], datas = [];
 17: let engVer = '-';
 18: const ok = (n, c, d) => { chk.push({ n, c: !!c, d: d == null ? '' : String(d) }); return !!c; };
 19: const data = (name, lines) => datas.push({ name, lines });
 20: const sha = b => crypto.createHash('sha256').update(b).digest('hex');
 21: const readJson = f => JSON.parse(fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, ''));
 22: const list = s => String(s == null ? '' : s).split(',').map(x => x.trim()).filter(Boolean);
 23: const fx = x => (x > 0 ? '+' : '') + Number(x).toFixed(2);
 24: const pad = (s, n) => String(s).padStart(n);
 25: 
 26: function report(verdict, err) {
 27:   fs.mkdirSync(path.join(RDIR, 'detail'), { recursive: true });
 28:   const L = [], pass = chk.filter(c => c.c).length;
 29:   L.push('#MT-REPORT v=report-1.0 step=' + STEP + ' ver=' + VER + ' verdict=' + verdict + ' ts=' + new Date().toISOString() + ' dur=' + ((Date.now() - T0) / 1000).toFixed(1) + 's');
 30:   L.push('#DIR ' + RDIR);
 31:   L.push('#ENV node=' + process.version + ' os=' + process.platform + '-' + process.arch + ' engines=' + engVer);
 32:   L.push('#CHK ' + pass + '/' + chk.length + ' ' + (pass === chk.length && !err ? 'PASS' : 'FAIL'));
 33:   for (const c of chk) if (!c.c) L.push('#FAIL ' + c.n + ' :: ' + c.d);
 34:   if (err) {
 35:     L.push('#ERR ' + String((err && err.message) || err));
 36:     for (const s of String((err && err.stack) || '').split('\n').slice(1, 7)) L.push('#AT ' + s.trim());
 37:   }
 38:   for (const s of sums) L.push('#SUM ' + s);
 39:   for (const d of datas) { L.push('#DATA ' + d.name + ' lines=' + d.lines.length); for (const x of d.lines) L.push(x); L.push('#END'); }
 40:   let txt = L.join('\n') + '\n';
 41:   if (Buffer.byteLength(txt) > 200 * 1024) txt = txt.slice(0, 200 * 1024) + '\n#TRUNC 200KB\n';
 42:   fs.mkdirSync(path.dirname(OUTF), { recursive: true });
 43:   fs.writeFileSync(OUTF, txt);
 44:   fs.writeFileSync(path.join(RDIR, 'FOR_OPUS.txt'), txt);
 45: }
