 47: // ---- copied from sz-lab-guard11.cjs ----
 48: function stats(tr) {
 49:   let n = tr.length, w = 0, sum = 0, gw = 0, gl = 0, eq = 0, pk = 0, mdd = 0, mfe = 0;
 50:   for (const t of tr) {
 51:     if (t.ret > 0) { w++; gw += t.ret; } else gl -= t.ret;
 52:     sum += t.ret; mfe += t.mfe; eq += t.ret; if (eq > pk) pk = eq; if (pk - eq > mdd) mdd = pk - eq;
 53:   }
 54:   return { n, w, sum, avg: n ? sum / n : 0, pf: gl > 0 ? gw / gl : (gw > 0 ? 99 : 0), mdd, avgMfe: n ? mfe / n : 0 };
 55: }
 56: function parseCsv(text) {
 57:   text = text.replace(/^\uFEFF/, '');
 58:   const rows = []; let row = [], f = '', q = false;
 59:   for (let i = 0; i < text.length; i++) {
 60:     const ch = text[i];
 61:     if (q) { if (ch === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += ch; }
 62:     else if (ch === '"') q = true;
 63:     else if (ch === ',') { row.push(f); f = ''; }
 64:     else if (ch === '\n') { row.push(f); rows.push(row); row = []; f = ''; }
 65:     else if (ch !== '\r') f += ch;
 66:   }
 67:   if (f !== '' || row.length) { row.push(f); rows.push(row); }
 68:   return rows.filter(r => r.length > 1 || r[0] !== '');
 69: }
 70: function num(s) { const t = String(s == null ? '' : s).replace(/[,\s+]/g, ''); return t === '' ? NaN : Number(t); }
 71: function stamp(ts, ds) {
 72:   let t = String(ts == null ? '' : ts).replace(/\D/g, ''); const d = ds != null ? String(ds).replace(/\D/g, '') : '';
 73:   if (t.length >= 14) return t.slice(0, 14);
 74:   if ((t.length === 6 || t.length === 5) && d.length >= 8) return d.slice(0, 8) + t.padStart(6, '0');
 75:   if (t.length === 4 && d.length >= 8) return d.slice(0, 8) + t + '00';
 76:   if (t.length === 10 || t.length === 13) {
 77:     const ms = t.length === 13 ? Number(t) : Number(t) * 1000;
 78:     return new Date(ms + 9 * 3600e3).toISOString().replace(/\D/g, '').slice(0, 14);
 79:   }
 80:   return null;
 81: }
 82: function loadTicksText(text) {
 83:   const rows = parseCsv(text);
 84:   if (rows.length < 2) throw new Error('empty csv');
 85:   const hdr = rows[0].map(x => x.trim().toLowerCase());
 86:   const find = names => { for (const nm of names) { const k = hdr.indexOf(nm); if (k >= 0) return k; } return -1; };
 87:   const iT = find(['cntr_tm', 'time', 'ts', 'datetime', 'timestamp', 'dt']);
 88:   const iD = find(['date', 'trading_date', 'tradingdate', 'trade_date', 'day']);
 89:   const iO = find(['open', 'open_pric', 'o']), iH = find(['high', 'high_pric', 'h']), iL = find(['low', 'low_pric', 'l']);
 90:   const iC = find(['close', 'cur_prc', 'c', 'price']), iV = find(['volume', 'trde_qty', 'vol', 'v', 'qty']);
 91:   if ([iT, iO, iH, iL, iC, iV].some(k => k < 0)) throw new Error('columns not found, header=' + hdr.join('|'));
 92:   const bars = [];
 93:   for (let r = 1; r < rows.length; r++) {
 94:     const row = rows[r], st = stamp(row[iT], iD >= 0 ? row[iD] : null);
 95:     if (!st) continue;
 96:     let o = Math.abs(num(row[iO])), h = Math.abs(num(row[iH])), l = Math.abs(num(row[iL])), c = Math.abs(num(row[iC])), v = Math.abs(num(row[iV]));
 97:     if (!(c > 0) || !isFinite(v)) continue;
 98:     if (!(o > 0)) o = c;
 99:     h = Math.max(h > 0 ? h : c, o, c); l = Math.min(l > 0 ? l : c, o, c);
100:     const y = +st.slice(0, 4), mo = +st.slice(4, 6), d = +st.slice(6, 8), hh = +st.slice(8, 10), mi = +st.slice(10, 12), ss = +st.slice(12, 14);
101:     bars.push({ d: st.slice(0, 8), hms: hh * 10000 + mi * 100 + ss, t: Date.UTC(y, mo - 1, d, hh, mi, ss) / 1000, o, h, l, c, v });
102:   }
103:   if (bars.length < 10) throw new Error('too few bars: ' + bars.length);
104:   if (bars[0].t > bars[bars.length - 1].t) bars.reverse();
105:   for (let i = 1; i < bars.length; i++) if (bars[i].t < bars[i - 1].t) { bars.sort((a, b) => a.t - b.t); break; }
106:   return bars;
107: }
108: function loadDaily2(dailyDir, code, date, warn) {
109:   const f = path.join(dailyDir, code + '.csv');
110:   if (!fs.existsSync(f)) { warn.push('no daily csv'); return null; }
111:   const rows = parseCsv(fs.readFileSync(f, 'utf8')), h = rows[0].map(x => x.trim().toLowerCase());
112:   const iD = h.indexOf('date'), iC = h.indexOf('close'), iP = h.indexOf('chg_pct');
113:   if (iD < 0 || iC < 0) { warn.push('daily columns missing'); return null; }
114:   const lst = rows.slice(1).map(r => ({ d: String(r[iD]).replace(/\D/g, '').slice(0, 8), c: Math.abs(num(r[iC])), p: iP >= 0 ? num(r[iP]) : NaN }))
115:     .filter(x => x.d.length === 8 && x.c > 0).sort((a, b) => a.d < b.d ? -1 : a.d > b.d ? 1 : 0);
116:   let k = -1; for (let j = 0; j < lst.length; j++) if (lst[j].d < date) k = j;
117:   if (k < 0) { warn.push('no prev daily row'); return null; }
118:   let chg = lst[k].p;
119:   if (!isFinite(chg) && k > 0) chg = (lst[k].c / lst[k - 1].c - 1) * 100;
120:   return { d: lst[k].d, c: lst[k].c, chg };
121: }
122: // ---- end copy ----
123: 
124: const TF = ['inPx', 'outPx', 'why', 'gross', 'ret', 'mfe', 'mae', 'bars', 'reached', 'held'];
125: const REJ = ['time', 'count', 'gap', 'lim', 'ema', 'disp', 'tick'];
126: function sameTr(a, b, off) {
127:   if (a.trades.length !== b.trades.length) return 'trades ' + a.trades.length + ' vs ' + b.trades.length;
128:   for (let k = 0; k < a.trades.length; k++) {
129:     const x = a.trades[k], y = b.trades[k];
130:     if (x.inI !== y.inI + off) return 'trade#' + (k + 1) + ' inI ' + x.inI + ' vs ' + (y.inI + off);
131:     if (x.outI !== y.outI + off) return 'trade#' + (k + 1) + ' outI ' + x.outI + ' vs ' + (y.outI + off);
132:     for (const f of TF) if (x[f] !== y[f]) return 'trade#' + (k + 1) + ' ' + f + ' ' + x[f] + ' vs ' + y[f];
133:   }
134:   return null;
135: }
136: function sameCnt(a, b) {
137:   for (const k of REJ) if (a.rej[k] !== b.rej[k]) return 'rej.' + k + ' ' + a.rej[k] + ' vs ' + b.rej[k];
138:   if (a.arms !== b.arms || a.sigs !== b.sigs || a.held !== b.held) return 'arms/sigs/held ' + [a.arms, a.sigs, a.held] + ' vs ' + [b.arms, b.sigs, b.held];
139:   return null;
140: }
141: function indDiff(a, b, start, N, off) {
142:   let safe = 0, stDir = 0, sig = 0, ema = 0;
143:   for (let j = start; j < N; j++) {
144:     const k = j - off;
145:     if (!!a.safe[j] !== !!b.safe[k]) safe++;
146:     if (a.stDir[j] !== b.stDir[k]) stDir++;
147:     if ((a.n[j] < a.sig[j]) !== (b.n[k] < b.sig[k])) sig++;
148:     if (a.ema[j] > 0 && b.ema[k] > 0) { const r = Math.abs(b.ema[k] / a.ema[j] - 1) * 100; if (r > ema) ema = r; }
149:   }
150:   return { safe, stDir, sig, ema };
151: }
152: 
153: function main() {
154:   fs.mkdirSync(path.join(RDIR, 'detail'), { recursive: true });
155:   const REF = Number(A('ref') || 800);
156:   const GRID = list(A('grid') || '0,50,100,150,200,300,400,600').map(Number).filter(x => x >= 0 && x < REF).sort((a, b) => a - b);
157:   const E = require(path.join(ROOT, 'tools', 'ui', 'engines.cjs'));
158:   engVer = E.VERSION;
159:   const vr = E.verify(ROOT);
160:   if (!ok('engine hash gate (' + E.VERSION + ')', vr && vr.ok, 'missing=' + JSON.stringify(vr && vr.missing))) return 'FAIL';
161:   const V1 = E.load(ROOT).V1;
162:   if (!ok('V1 api prep/compute/simulate', V1 && ['prep', 'compute', 'simulate'].every(k => typeof V1[k] === 'function'), Object.keys(V1 || {}).join(','))) return 'FAIL';
163: 
164:   // strategies (same rule as lab: frozen hash-checked, then survivors, then candidates)
165:   const SD = path.join(ROOT, 'strategies'), man = readJson(path.join(SD, 'manifest.json')), lib = {};
166:   for (const f of fs.readdirSync(path.join(SD, 'frozen')).filter(x => x.endsWith('.json'))) {
167:     const s = readJson(path.join(SD, 'frozen', f));
168:     if (!man.frozen || man.frozen[s.id] !== sha(JSON.stringify(s.params))) throw new Error('frozen strategy modified or unknown: ' + s.id);
169:     lib[s.id] = s;
170:   }
171:   const B = lib[man.baseline]; if (!B) throw new Error('baseline missing: ' + man.baseline);
172:   const SURV = path.join(SD, 'survivors');
173:   if (fs.existsSync(SURV)) for (const f of fs.readdirSync(SURV).filter(x => x.endsWith('.json'))) { const s = readJson(path.join(SURV, f)); if (!lib[s.id]) lib[s.id] = s; }
174:   const resolve = id => {
175:     if (lib[id]) return lib[id];
176:     const f = path.join(SD, 'candidates', id + '.json'); if (!fs.existsSync(f)) throw new Error('strategy not found: ' + id);
177:     const c = readJson(f), b = lib[c.base || B.id]; if (!b) throw new Error('base not found: ' + c.base);
178:     const p = Object.assign({}, b.params);
179:     for (const k of Object.keys(c.overrides || {})) { if (!(k in p)) throw new Error('unknown param ' + k + ' in ' + id); p[k] = c.overrides[k]; }
180:     return { id: c.id, name: c.name, params: p, engine: c.engine || 'v1' };
181:   };
182:   let sids = list(A('strategies') || 'S000,C013'); sids = [B.id].concat(sids.filter(x => x !== B.id));
183:   const strats = sids.map(resolve);
184:   for (const s of strats) if ((s.engine || 'v1') !== 'v1') throw new Error(s.id + ': engine ' + s.engine + ' not supported');
185:   const Match = B.params.Match || '_AL_120t_';
186: 
187:   const loadItem = (tickDir, dailyDir, f) => {
188:     const buf = fs.readFileSync(path.join(tickDir, f)), bars = loadTicksText(buf.toString('utf8'));
189:     const code = f.split('_')[0], dm = f.match(/(\d{8})\.csv$/i), m = f.match(/_(\d+)t_/);
190:     const date = dm ? dm[1] : bars[bars.length - 1].d, start = bars.findIndex(b => b.d === date);
191:     if (start < 0) throw new Error('target date not in file');
192:     const warn = [], dly = loadDaily2(dailyDir, code, date, warn);
193:     return { f, code, date, bars, start, scope: m ? Number(m[1]) : 120, dly, warn, sha: sha(buf) };
194:   };
195:   const run = (it, bars, start, params) => {
196:     const P = V1.prep(Object.assign({}, params, { Date: '', TickScope: it.scope }));
197:     const dayComplete = bars[start].hms <= P._sessMax;
198:     let limKind = null;
199:     if (it.dly && isFinite(it.dly.chg)) { if (it.dly.chg >= P.LimPct) limKind = 'limit'; else if (it.dly.chg >= P.SurgePct) limKind = 'surge'; }
200:     const ind = V1.compute(bars, P);
201:     const r = V1.simulate(bars, ind, P, { start, date: it.date, dayComplete, limKind, prevClose: it.dly ? it.dly.c : null, prevChg: it.dly ? it.dly.chg : null });
202:     return { r, ind };
203:   };
204: 
205:   // gate 2: reproduce 11/02 from data\ticks + data\daily
206:   const oldT = path.join(ROOT, 'data', 'ticks'), oldD = path.join(ROOT, 'data', 'daily');
207:   const oldItems = fs.readdirSync(oldT).filter(f => f.toLowerCase().endsWith('.csv') && f.includes(Match)).sort().map(f => loadItem(oldT, oldD, f));
208:   const EXP = { S000: { n: 33, sum: '5.94' }, C013: { n: 31, sum: '8.29' } };
209:   const rl = ['strategy items trades     sum    PF   MDD  expected'];
210:   let reproOk = true;
211:   for (const s of strats) {
212:     const st = stats([].concat(...oldItems.map(it => run(it, it.bars, it.start, s.params).r.trades))), e = EXP[s.id];
213:     rl.push(s.id.padEnd(8) + pad(oldItems.length, 6) + pad(st.n, 7) + pad(fx(st.sum), 8) + pad(st.pf.toFixed(2), 6) + pad(st.mdd.toFixed(2), 6) + '  ' + (e ? e.n + '/' + e.sum : '-'));
214:     if (e && !ok('repro 11/02 ' + s.id, st.n === e.n && st.sum.toFixed(2) === e.sum, 'n=' + st.n + ' sum=' + st.sum.toFixed(2) + ' expected n=' + e.n + ' sum=' + e.sum)) reproOk = false;
215:   }
216:   data('repro_1102', rl);
217:   if (!reproOk) return 'FAIL';
218: 
219:   // gate 3: data\rest pipeline = data\ticks pipeline on the S3 parity file
220:   const restT = path.join(ROOT, 'data', 'rest', 'ticks'), restD = path.join(ROOT, 'data', 'rest', 'daily');
221:   const PF = '0011A0_AL_120t_20261102.csv', a0 = oldItems.find(x => x.f === PF);
222:   if (!ok('rest parity file present', a0 && fs.existsSync(path.join(restT, PF)), PF)) return 'FAIL';
223:   const b0 = loadItem(restT, restD, PF);
224:   ok('rest bytes = data/ticks (' + PF + ')', a0.sha === b0.sha, a0.sha.slice(0, 12) + ' vs ' + b0.sha.slice(0, 12));
225:   for (const s of strats) {
226:     const x = run(a0, a0.bars, a0.start, s.params).r, y = run(b0, b0.bars, b0.start, s.params).r;
227:     const m = sameTr(x, y, 0) || sameCnt(x, y);
228:     ok('rest pipeline = old pipeline ' + s.id, !m, m);
229:   }
230:   if (chk.some(c => !c.c)) return 'FAIL';
231: 
232:   // scan archive
233:   const files = fs.readdirSync(restT).filter(f => f.toLowerCase().endsWith('.csv') && f.includes(Match)).sort();
234:   const cov = [], full = [], exL = []; let excl = 0, noDaily = 0;
235:   for (const f of files) {
236:     let it; try { it = loadItem(restT, restD, f); } catch (e) { excl++; if (exL.length < 20) exL.push(f + ': ' + e.message); continue; }
237:     if (!it.dly) noDaily++;
238:     cov.push({ code: it.code, date: it.date, warm: it.start });
239:     if (it.start >= REF) full.push(it);
240:   }
241:   if (!ok('full-warmup stock-days >= 1', full.length > 0, 'full=' + full.length)) return 'FAIL';
242: 
243:   // sensitivity
244:   const agg = {}, ex = {}, rows = ['code,date,warm,strategy,W,sameTrades,sameAll,refN,wN,refSum,wSum,safeMis,stDirMis,sigMis,emaRelMaxPct,msg'];
245:   for (const s of strats) for (const it of full) {
246:     const R0 = run(it, it.bars, it.start, s.params), refSum = R0.r.trades.reduce((a, t) => a + t.ret, 0);
247:     for (const W of GRID) {
248:       const off = it.start - W, R1 = run(it, it.bars.slice(off), W, s.params);
249:       const mt = sameTr(R0.r, R1.r, off), mc = mt || sameCnt(R0.r, R1.r);
250:       const id = indDiff(R0.ind, R1.ind, it.start, it.bars.length, off), wSum = R1.r.trades.reduce((a, t) => a + t.ret, 0);
251:       const k = s.id + '|' + W;
252:       const g = agg[k] || (agg[k] = { items: 0, sameT: 0, sameA: 0, act: 0, actSame: 0, refN: 0, wN: 0, refSum: 0, wSum: 0, safe: 0, stDir: 0, sig: 0, ema: 0 });
253:       g.items++; if (!mt) g.sameT++; if (!mc) g.sameA++;
254:       if (R0.r.trades.length || R1.r.trades.length) { g.act++; if (!mt) g.actSame++; }
255:       g.refN += R0.r.trades.length; g.wN += R1.r.trades.length; g.refSum += refSum; g.wSum += wSum;
256:       g.safe += id.safe; g.stDir += id.stDir; g.sig += id.sig; if (id.ema > g.ema) g.ema = id.ema;
257:       if (mt) { const e = ex[k] || (ex[k] = []); if (e.length < 3) e.push(it.code + ' ' + it.date + ': ' + mt); }
258:       rows.push([it.code, it.date, it.start, s.id, W, mt ? 0 : 1, mc ? 0 : 1, R0.r.trades.length, R1.r.trades.length, refSum.toFixed(3), wSum.toFixed(3),
259:         id.safe, id.stDir, id.sig, id.ema.toFixed(4), String(mc || '').replace(/,/g, ';')].join(','));
260:     }
261:   }
262:   fs.writeFileSync(path.join(RDIR, 'detail', 'items.csv'), rows.join('\r\n') + '\r\n');
263: 
264:   const tl = ['strategy    W items sameTr% sameAll% activeSame refN   wN  refSum    wSum safeMis stDirMis sigMis emaMax%'];
265:   for (const s of strats) for (const W of GRID) {
266:     const g = agg[s.id + '|' + W];
267:     tl.push(s.id.padEnd(8) + pad(W, 5) + pad(g.items, 6) + pad((g.sameT / g.items * 100).toFixed(1), 8) + pad((g.sameA / g.items * 100).toFixed(1), 9) +
268:       pad(g.actSame + '/' + g.act, 11) + pad(g.refN, 5) + pad(g.wN, 5) + pad(fx(g.refSum), 8) + pad(fx(g.wSum), 8) + pad(g.safe, 8) + pad(g.stDir, 9) + pad(g.sig, 7) + pad(g.ema.toFixed(3), 8));
269:   }
270:   data('sensitivity (W vs REF ' + REF + ', target-day trades)', tl);
271:   const xl = [];
272:   for (const s of strats) for (const W of GRID) for (const e of ex[s.id + '|' + W] || []) xl.push(s.id + ' W=' + W + ' ' + e);
273:   data('first_diffs (max 3 per row)', xl);
274: 
275:   const allAt = (W, thr) => strats.every(s => { const g = agg[s.id + '|' + W]; return g && g.sameT / g.items >= thr; });
276:   const rec100 = GRID.find(W => allAt(W, 1)), rec99 = GRID.find(W => allAt(W, 0.99));
